<?php
/**
 * RIVROSS Projects showcase page.
 *
 * @package Rivross_Corporate
 */

get_header();
$page_url = get_permalink();
$assets   = get_theme_file_uri( '/assets/images/' );
$hero_image = get_theme_mod( 'rivross_projects_hero_image', $assets . 'projects/projects-hero.png' );
$status_filter = isset( $_GET['project_status'] ) ? sanitize_text_field( wp_unslash( $_GET['project_status'] ) ) : '';
$type_filter = isset( $_GET['project_type'] ) ? sanitize_title( wp_unslash( $_GET['project_type'] ) ) : '';
$location_filter = isset( $_GET['project_location'] ) ? sanitize_text_field( wp_unslash( $_GET['project_location'] ) ) : '';
$project_types = get_terms( array( 'taxonomy' => 'rivross_project_type', 'hide_empty' => true ) );
$project_types = is_wp_error( $project_types ) ? array() : $project_types;
$all_projects = get_posts( array( 'post_type' => 'rivross_project', 'post_status' => 'publish', 'posts_per_page' => -1, 'orderby' => 'title', 'order' => 'ASC' ) );
$locations = array();
foreach ( $all_projects as $project ) { $item_location = rivross_project_meta( $project->ID, 'location' ); if ( $item_location && ! in_array( $item_location, $locations, true ) ) { $locations[] = $item_location; } }
$filter_url = static function ( $overrides = array() ) use ( $page_url, $status_filter, $type_filter, $location_filter ) {
	$args = array( 'project_status' => $status_filter, 'project_type' => $type_filter, 'project_location' => $location_filter );
	foreach ( $overrides as $key => $value ) { $args[ $key ] = $value; }
	return add_query_arg( array_filter( $args ), $page_url );
};
$sections = array(
	'Ongoing' => array( 'title' => __( 'Ongoing Projects', 'rivross-corporate' ), 'anchor' => 'ongoing-projects', 'action' => __( 'View All Ongoing Projects', 'rivross-corporate' ) ),
	'Upcoming' => array( 'title' => __( 'Upcoming Projects', 'rivross-corporate' ), 'anchor' => 'upcoming-projects', 'action' => __( 'View All Upcoming Projects', 'rivross-corporate' ) ),
	'Completed' => array( 'title' => __( 'Completed Projects', 'rivross-corporate' ), 'anchor' => 'completed-projects', 'action' => __( 'View All Completed Projects', 'rivross-corporate' ) ),
);
?>
<section class="projects-hero" style="--projects-hero-image:url('<?php echo esc_url( $hero_image ); ?>');"><div class="rivross-container rivross-container--wide projects-hero__inner"><nav class="projects-hero__breadcrumb" aria-label="<?php esc_attr_e( 'Breadcrumb', 'rivross-corporate' ); ?>"><a href="<?php echo esc_url( home_url( '/' ) ); ?>"><?php esc_html_e( 'Home', 'rivross-corporate' ); ?></a><span>›</span><a href="<?php echo esc_url( home_url( '/real-estate/' ) ); ?>"><?php esc_html_e( 'Real Estate', 'rivross-corporate' ); ?></a><span>›</span><span><?php esc_html_e( 'Projects', 'rivross-corporate' ); ?></span></nav><div class="projects-hero__copy"><h1><span><?php echo esc_html( get_theme_mod( 'rivross_projects_hero_line_1', __( 'Our Projects,', 'rivross-corporate' ) ) ); ?></span><strong><?php echo esc_html( get_theme_mod( 'rivross_projects_hero_line_2', __( 'Building Better Tomorrows', 'rivross-corporate' ) ) ); ?></strong></h1><i></i><p><?php echo esc_html( get_theme_mod( 'rivross_projects_hero_description', __( 'Discover our diverse portfolio of real estate developments that redefine modern living and create lasting value.', 'rivross-corporate' ) ) ); ?></p></div></div></section>

<main class="projects-page"><section class="projects-filters"><div class="rivross-container rivross-container--wide"><div class="projects-filters__inner"><div class="projects-status"><span><?php esc_html_e( 'View Projects By Status', 'rivross-corporate' ); ?></span><div><a class="<?php echo '' === $status_filter ? 'is-active' : ''; ?>" href="<?php echo esc_url( $filter_url( array( 'project_status' => '' ) ) ); ?>"><?php echo rivross_icon( 'grid' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?><?php esc_html_e( 'All Projects', 'rivross-corporate' ); ?></a><a class="<?php echo 'Ongoing' === $status_filter ? 'is-active' : ''; ?>" href="<?php echo esc_url( $filter_url( array( 'project_status' => 'Ongoing' ) ) ); ?>"><?php echo rivross_icon( 'building' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?><?php esc_html_e( 'Ongoing', 'rivross-corporate' ); ?></a><a class="<?php echo 'Upcoming' === $status_filter ? 'is-active' : ''; ?>" href="<?php echo esc_url( $filter_url( array( 'project_status' => 'Upcoming' ) ) ); ?>"><?php echo rivross_icon( 'calendar' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?><?php esc_html_e( 'Upcoming', 'rivross-corporate' ); ?></a><a class="<?php echo 'Completed' === $status_filter ? 'is-active' : ''; ?>" href="<?php echo esc_url( $filter_url( array( 'project_status' => 'Completed' ) ) ); ?>"><?php echo rivross_icon( 'check' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?><?php esc_html_e( 'Completed', 'rivross-corporate' ); ?></a></div></div><form class="projects-selects" method="get" action="<?php echo esc_url( $page_url ); ?>"><label><span><?php esc_html_e( 'Property Type', 'rivross-corporate' ); ?></span><select name="project_type"><option value=""><?php esc_html_e( 'All Types', 'rivross-corporate' ); ?></option><?php foreach ( $project_types as $term ) : ?><option value="<?php echo esc_attr( $term->slug ); ?>" <?php selected( $type_filter, $term->slug ); ?>><?php echo esc_html( $term->name ); ?></option><?php endforeach; ?></select></label><label><span><?php esc_html_e( 'Location', 'rivross-corporate' ); ?></span><select name="project_location"><option value=""><?php esc_html_e( 'All Locations', 'rivross-corporate' ); ?></option><?php foreach ( $locations as $item ) : ?><option value="<?php echo esc_attr( $item ); ?>" <?php selected( $location_filter, $item ); ?>><?php echo esc_html( $item ); ?></option><?php endforeach; ?></select></label><?php if ( $status_filter ) : ?><input type="hidden" name="project_status" value="<?php echo esc_attr( $status_filter ); ?>"><?php endif; ?><button class="rivross-button" type="submit"><?php esc_html_e( 'Filter', 'rivross-corporate' ); ?> <?php echo rivross_icon( 'search' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></button></form></div></div></section>

	<div class="rivross-container rivross-container--wide projects-sections"><?php foreach ( $sections as $status => $section ) : if ( $status_filter && $status_filter !== $status ) { continue; } $args = array( 'post_type' => 'rivross_project', 'post_status' => 'publish', 'posts_per_page' => 4, 'orderby' => 'date', 'order' => 'ASC', 'meta_query' => array( array( 'key' => '_rivross_project_status', 'value' => $status ) ) ); if ( $type_filter ) { $args['tax_query'] = array( array( 'taxonomy' => 'rivross_project_type', 'field' => 'slug', 'terms' => $type_filter ) ); } if ( $location_filter ) { $args['meta_query'][] = array( 'key' => '_rivross_project_location', 'value' => $location_filter ); } $query = new WP_Query( $args ); if ( ! $query->have_posts() ) { continue; } ?><section id="<?php echo esc_attr( $section['anchor'] ); ?>" class="projects-group"><div class="projects-group__heading"><h2><?php echo esc_html( $section['title'] ); ?></h2><i></i><a href="<?php echo esc_url( $filter_url( array( 'project_status' => $status ) ) ); ?>"><?php echo esc_html( $section['action'] ); ?> <?php echo rivross_icon( 'arrow' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></a></div><div class="projects-grid"><?php while ( $query->have_posts() ) : $query->the_post(); $project_id = get_the_ID(); $project_terms = get_the_terms( $project_id, 'rivross_project_type' ); $type_label = ! empty( $project_terms ) && ! is_wp_error( $project_terms ) ? $project_terms[0]->name : rivross_project_meta( $project_id, 'type', __( 'Project', 'rivross-corporate' ) ); ?><article class="project-card"><a class="project-card__media" href="<?php the_permalink(); ?>"><img src="<?php echo esc_url( rivross_project_image_url( $project_id ) ); ?>" alt="<?php echo esc_attr( get_the_title() ); ?>"><span class="project-card__badge project-card__badge--<?php echo esc_attr( sanitize_title( $status ) ); ?>"><?php echo esc_html( $status ); ?></span><span class="project-card__favorite"><?php echo rivross_icon( 'heart' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></span></a><div class="project-card__body"><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p class="project-card__location"><?php echo rivross_icon( 'pin' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?><?php echo esc_html( rivross_project_meta( $project_id, 'location' ) ); ?></p><div class="project-card__specs"><span><?php echo rivross_icon( 'bed' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?><?php echo esc_html( rivross_project_meta( $project_id, 'bedrooms' ) ); ?></span><span><?php echo rivross_icon( 'ruler' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?><?php echo esc_html( rivross_project_meta( $project_id, 'size' ) ); ?></span><span><?php echo rivross_icon( 'car' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?><?php echo esc_html( rivross_project_meta( $project_id, 'parking' ) ); ?></span></div><strong class="project-card__price"><?php echo esc_html( rivross_project_meta( $project_id, 'price' ) ); ?></strong><small><?php echo esc_html( rivross_project_meta( $project_id, 'timeline' ) ); ?></small><a class="project-card__link" href="<?php the_permalink(); ?>"><?php esc_html_e( 'View Details', 'rivross-corporate' ); ?> <?php echo rivross_icon( 'arrow' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></a></div></article><?php endwhile; wp_reset_postdata(); ?></div></section><?php endforeach; ?></div>
	<section class="projects-cta"><div class="rivross-container rivross-container--wide projects-cta__inner"><span><?php echo rivross_icon( 'phone' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></span><div><h2><?php echo esc_html( get_theme_mod( 'rivross_projects_cta_title', __( 'Let’s Build Something Great Together', 'rivross-corporate' ) ) ); ?></h2><p><?php echo esc_html( get_theme_mod( 'rivross_projects_cta_description', __( 'Have a project in mind? Partner with RIVROSS for trusted development and outstanding results.', 'rivross-corporate' ) ) ); ?></p></div><div class="projects-cta__actions"><a class="rivross-button" href="<?php echo esc_url( home_url( '/contact-us/#contact-form' ) ); ?>"><?php esc_html_e( 'Discuss Your Project', 'rivross-corporate' ); ?> <?php echo rivross_icon( 'arrow' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></a><a class="rivross-button projects-cta__outline" href="<?php echo esc_url( home_url( '/contact-us/' ) ); ?>"><?php esc_html_e( 'Contact Us', 'rivross-corporate' ); ?> <?php echo rivross_icon( 'arrow' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></a></div></div></section>
</main>
<?php get_footer(); ?>
